// Logic Engine: Cut-off Validation & Materiality Assessment (SA 320 / PSAK 72)
const invoice = $('Google Sheets Trigger (New Invoice)').first().json;
const shipping =$input.first().json;

const TE_THRESHOLD = 2100000000; // Performance Materiality PT NTP (Rp 2.1 Miliar)
const invoiceDate = new Date(invoice.invoice_date);
const blDate = shipping && shipping.bl_date ? new Date(shipping.bl_date) : null;

let isCutoffError = false;
let riskLevel = 'NONE';
let requiresAJE = false;

// Validation Rule: FOB Shipping Point Control Transfer
if (!blDate || blDate > invoiceDate) {
  isCutoffError = true;
  if (Number(invoice.net_amount) >= TE_THRESHOLD) {
    riskLevel = 'MATERIAL_TE_EXCEEDED';
    requiresAJE = true;
  } else {
    riskLevel = 'IMMATERIAL_DEVIATION';
  }
}

return [{
  json: {
    invoice_id: invoice.invoice_id,
    customer_name: invoice.customer_name,
    net_amount: Number(invoice.net_amount),
    invoice_date: invoice.invoice_date,
    bl_number: shipping ? (shipping.bl_number || 'MISSING') : 'MISSING',
    bl_date: shipping ? (shipping.bl_date || null) : null,
    cutoff_error: isCutoffError,
    risk_level: riskLevel,
    requires_proposed_aje: requiresAJE,
    anomali_flag: isCutoffError ? 'L2_PREMATURE_REVENUE' : 'NONE'
  }
}];

